<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -DBENCHMARK_DATA_PREDOWNLOAD_DIR=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;$(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">pwd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">)/bench_data&quot;</span></span>
